                raise ValueError(
                    f"failed to cast to '{dtype}' (Exception was: {orig})"
                ) from orig

    index, columns = _get_axes(*values.shape, index=index, columns=columns)

    # Convert the numpy array to a list of Series
    if values.ndim == 2:
        values_list = [pd.Series(row, index=index) for row in values.T]
    else:
        values_list = [pd.Series(values, index=index)]

    # Create a new DataFrame from the list of Series
    df = pd.DataFrame({col: s for col, s in zip(columns, values_list)})

    return df
